package com.fixmer.genesis.technology.scripts;
import java.io.*;import java.net.URI;import java.util.*;import java.util.regex.*;
/** Validated project dependencies; pure rendering, no downloads or script execution. */
public final class ProjectDependencies {
 public static final String CONFIG="genesis-dependencies.properties",SCRIPT="genesis-dependencies.gradle",TOML="src/main/resources/META-INF/neoforge.mods.toml";
 public static final List<String> FILES=List.of("build.gradle",CONFIG,SCRIPT,TOML);
 private static final String BEGIN="// BEGIN GENESIS DEPENDENCIES",END="// END GENESIS DEPENDENCIES",TB="# BEGIN GENESIS DEPENDENCIES",TE="# END GENESIS DEPENDENCIES";
 public enum Mode{LIBRARY,COMPILE_ONLY,EMBED,MOD}
 public record Dependency(Mode mode,String coordinate,String modId,String range,String type,String side){
  public Dependency{Objects.requireNonNull(mode);if(!validCoordinate(coordinate))throw new IllegalArgumentException("Use group:artifact:version (fixed version, optional classifier)");
   if(mode==Mode.MOD){if((modId==null||!modId.matches("[a-z][a-z0-9_]{1,63}"))||Set.of("minecraft","neoforge").contains(modId)||!validRange(range)||!Set.of("required","optional").contains(type)||!Set.of("BOTH","CLIENT","SERVER").contains(side))throw new IllegalArgumentException("Invalid mod ID, version range, dependency type or side");}
   else if(!"".equals(modId)||!("".equals(range)||mode==Mode.EMBED&&validRange(range))||!"".equals(type)||!"".equals(side))throw new IllegalArgumentException("Library has mod metadata");
   if(mode==Mode.EMBED&&!range.isEmpty()&&!DependencySyntax.numericContains(range,coordinate.split(":")[2]))throw new IllegalArgumentException("Preferred library version is outside the embedding range");
   if(mode==Mode.EMBED&&coordinate.split(":").length!=3)throw new IllegalArgumentException("Embedded dependencies require group:artifact:version");
  }
  public String key(){String[] p=coordinate.split(":");return p[0]+":"+p[1]+(p.length==4?":"+p[3]:"");}
  public static Dependency embedded(String coordinate,String range){return new Dependency(Mode.EMBED,coordinate,"",range,"","");}
  public static Dependency library(Mode mode,String coordinate){return new Dependency(mode,coordinate,"","","","");}
 }
 public record Config(List<Dependency> dependencies,List<String> repositories,boolean localLibraries){
  public Config{dependencies=List.copyOf(dependencies);repositories=List.copyOf(repositories);if(dependencies.size()>64||repositories.size()>16)throw new IllegalArgumentException("Dependency count limit");var keys=new HashSet<String>();var mods=new HashSet<String>();for(var d:dependencies){if(!keys.add(d.key())||d.mode()==Mode.MOD&&!mods.add(d.modId()))throw new IllegalArgumentException("Duplicate dependency");}var urls=new HashSet<String>();for(String r:repositories)if(!validRepository(r)||!urls.add(r))throw new IllegalArgumentException("Invalid or duplicate HTTPS Maven repository");}
  public Config add(Dependency d){var list=new ArrayList<>(dependencies);list.add(d);return new Config(list,repositories,localLibraries);}
  public Config remove(int index){var list=new ArrayList<>(dependencies);list.remove(index);return new Config(list,repositories,localLibraries);}
  public Config repository(String url){var list=new ArrayList<>(repositories);list.add(url);return new Config(dependencies,list,localLibraries);}
 }
 public record State(Map<String,String> files){public State{files=Map.copyOf(files);}public Config config()throws IOException{return parse(files.getOrDefault(CONFIG,""));}}
 private ProjectDependencies(){}
 public static boolean validCoordinate(String s){return s!=null&&s.length()<=256&&s.matches("[A-Za-z0-9_][A-Za-z0-9_.-]*:[A-Za-z0-9_][A-Za-z0-9_.-]*:[A-Za-z0-9_][A-Za-z0-9_.-]*(?::[A-Za-z0-9_][A-Za-z0-9_.-]*)?")&&!s.split(":")[2].toUpperCase(Locale.ROOT).contains("SNAPSHOT")&&!s.split(":")[2].toLowerCase(Locale.ROOT).startsWith("latest.");}
 public static boolean validRange(String s){return DependencySyntax.validRange(s);}
 public static boolean validRepository(String s){try{var u=URI.create(s);return s.length()<=1024&&s.matches("[A-Za-z0-9:/._%~-]+")&&"https".equals(u.getScheme())&&u.getHost()!=null&&u.getUserInfo()==null&&u.getQuery()==null&&u.getFragment()==null;}catch(RuntimeException bad){return false;}}
 public static Config parse(String text)throws IOException{
  if(text.isEmpty())return new Config(List.of(),List.of(),false);if(text.length()>32768)throw new IOException("Dependency configuration limit");var values=new Properties(){@Override public synchronized Object put(Object key,Object value){if(containsKey(key))throw new IllegalArgumentException("Duplicate declaration");return super.put(key,value);}};
  try{values.load(new StringReader(text));if(!"1".equals(values.getProperty("format")))throw new IllegalArgumentException("Unsupported dependency format");String local=values.getProperty("localLibraries","false");if(!Set.of("true","false").contains(local))throw new IllegalArgumentException("Invalid localLibraries value");var deps=new TreeMap<Integer,Dependency>();var repos=new TreeMap<Integer,String>();
   for(String key:values.stringPropertyNames()){if(key.equals("format")||key.equals("localLibraries"))continue;if(key.matches("repository\\.[0-9]{1,2}")){int n=Integer.parseInt(key.substring(11));if(n>=16||repos.putIfAbsent(n,values.getProperty(key))!=null)throw new IllegalArgumentException("Invalid repository index");}
    else if(key.matches("dependency\\.[0-9]{1,2}")){int n=Integer.parseInt(key.substring(11));String[] p=values.getProperty(key).split("\\|",-1);if(p.length!=6||n>=64||deps.putIfAbsent(n,new Dependency(Mode.valueOf(p[0]),p[1],p[2],p[3],p[4],p[5]))!=null)throw new IllegalArgumentException("Invalid dependency index");}else throw new IllegalArgumentException("Unknown declaration");}
   if(!deps.isEmpty()&&deps.lastKey()!=deps.size()-1||!repos.isEmpty()&&repos.lastKey()!=repos.size()-1)throw new IllegalArgumentException("Missing dependency/repository index");return new Config(new ArrayList<>(deps.values()),new ArrayList<>(repos.values()),Boolean.parseBoolean(local));
  }catch(IllegalArgumentException bad){throw new IOException("Malformed dependencies: "+bad.getMessage(),bad);}
 }
 public static String encode(Config c){var s=new StringBuilder("# Managed by Genesis dependency manager\nformat=1\nlocalLibraries="+c.localLibraries()+"\n");for(int i=0;i<c.repositories().size();i++)s.append("repository.").append(i).append('=').append(c.repositories().get(i)).append('\n');for(int i=0;i<c.dependencies().size();i++){var d=c.dependencies().get(i);s.append("dependency.").append(i).append('=').append(d.mode()).append('|').append(d.coordinate()).append('|').append(d.modId()).append('|').append(d.range()).append('|').append(d.type()).append('|').append(d.side()).append('\n');}if(s.length()>32768)throw new IllegalArgumentException("Dependency configuration exceeds 32 KiB");return s.toString();}
 private static String without(String text,String begin,String end)throws IOException{
  int a=text.indexOf(begin),b=text.indexOf(end);if(a<0&&b<0)return text;if(a<0||b<a||text.indexOf(begin,a+begin.length())>=0||text.indexOf(end,b+end.length())>=0)throw new IOException("Broken or duplicate Genesis managed block");return text.substring(0,a)+text.substring(b+end.length()).replaceFirst("^\\r?\\n","");
 }
 public static void verifyResolved(Config config,Collection<java.nio.file.Path> jars)throws IOException{var versions=new HashMap<String,String>();for(var file:jars)for(var e:JarInspection.modVersions(file).entrySet()){String old=versions.putIfAbsent(e.getKey(),e.getValue());if(old!=null&&!old.equals(e.getValue()))throw new IOException("Conflicting resolved mod versions: "+e.getKey());}for(var d:config.dependencies())if(d.mode()==Mode.MOD){String actual=versions.get(d.modId());if(actual==null){if(d.type().equals("required"))throw new IOException("Resolved artifact does not provide required modId: "+d.modId());continue;}if(actual.isBlank()||actual.contains("${"))throw new IOException("Cannot verify resolved mod version: "+d.modId());if(!DependencySyntax.numericContains(d.range(),actual))throw new IOException("Resolved mod "+d.modId()+" version "+actual+" is outside "+d.range());}}
 public static Map<String,String> render(State state,Config c)throws IOException{
  String build=state.files().get("build.gradle");if(build==null)throw new IOException("Dependency manager requires build.gradle (Groovy)");
  String toml=state.files().get(TOML);boolean neo=DependencySyntax.neo(build);if(c.dependencies().stream().anyMatch(d->d.mode()==Mode.MOD||d.mode()==Mode.EMBED)&&(!neo||toml==null))throw new IOException("Mod dependencies and embedding require a NeoGradle NeoForge project");
  Config old=state.config();String existing=state.files().get(SCRIPT);if(existing!=null&&!existing.equals(script(old,neo))&&!existing.equals(legacyScript(old,neo)))throw new IOException("Managed dependency script changed externally; preserve edits before updating");
  without(build,BEGIN,END);
  String owned=BEGIN+"\napply from: '"+SCRIPT+"'\n"+END;
  if(build.contains(BEGIN)&&!build.substring(build.indexOf(BEGIN),build.indexOf(END)+END.length()).equals(owned))throw new IOException("Managed build block changed externally");
  String manual=without(build,BEGIN,END);for(var d:c.dependencies())if(DependencySyntax.declares(manual,d.coordinate()))throw new IOException("Dependency is already declared manually: "+d.key());if(DependencySyntax.gradle(manual).contains("genesis-dependencies.gradle"))throw new IOException("Dependency script is already applied outside managed block");
  var out=new LinkedHashMap<String,String>();out.put("build.gradle",manual+(manual.endsWith("\n")?"":"\n")+BEGIN+"\napply from: '"+SCRIPT+"'\n"+END+"\n");out.put(CONFIG,encode(c));out.put(SCRIPT,script(c,neo));
  if(toml!=null){String original=without(toml,TB,TE);var ids=DependencySyntax.modIds(original);int mods=ids.getOrDefault("mods",List.of()).size();String id=mods==1?ids.get("mods").get(0):"";
   if(mods!=1&&!c.dependencies().stream().filter(d->d.mode()==Mode.MOD).toList().isEmpty())throw new IOException("Exactly one mod declaration is required for automatic dependency metadata");if(toml.contains(TB)){int a=toml.indexOf(TB),b=toml.indexOf(TE);if(b<a||!toml.substring(a,b+TE.length()).equals(modBlock(old,id)))throw new IOException("Managed mod metadata changed externally");}
   var tail=new StringBuilder(TB+"\n");
   for(var d:c.dependencies())if(d.mode()==Mode.MOD){if(d.modId().equals(id))throw new IOException("A mod cannot depend on itself");if(ids.entrySet().stream().filter(e->e.getKey().startsWith("dependencies.")).anyMatch(e->e.getValue().contains(d.modId())))throw new IOException("Mod dependency is already declared manually: "+d.modId());tail.append("[[dependencies.").append(id).append("]]\nmodId=\"").append(d.modId()).append("\"\ntype=\"").append(d.type()).append("\"\nversionRange=\"").append(d.range()).append("\"\nordering=\"NONE\"\nside=\"").append(d.side()).append("\"\n");}
   out.put(TOML,original+(original.endsWith("\n")?"":"\n")+tail+TE+"\n");}
  return Collections.unmodifiableMap(out);
 }
 private static String modBlock(Config c,String owner){var s=new StringBuilder(TB+"\n");for(var d:c.dependencies())if(d.mode()==Mode.MOD)s.append("[[dependencies.").append(owner).append("]]\nmodId=\"").append(d.modId()).append("\"\ntype=\"").append(d.type()).append("\"\nversionRange=\"").append(d.range()).append("\"\nordering=\"NONE\"\nside=\"").append(d.side()).append("\"\n");return s.append(TE).toString();}
 static String script(Config c,boolean neo){
  var s=new StringBuilder("// Generated by Genesis; edit through the dependency manager\nrepositories {\n    mavenCentral()\n");for(String r:c.repositories())s.append("    maven { url = uri('").append(r).append("') }\n");s.append("}\ndependencies {\n");if(c.localLibraries())s.append("    implementation fileTree(dir: 'libraries', includes: ['*.jar', '*.JAR'])\n");
  for(var d:c.dependencies()){String configuration=d.mode()==Mode.COMPILE_ONLY?"compileOnly":d.mode()==Mode.MOD&&d.type().equals("optional")?"compileOnly":"implementation";s.append("    ").append(configuration).append(" '").append(d.coordinate()).append("'\n");if(d.mode()==Mode.EMBED){String[] p=d.coordinate().split(":");s.append("    jarJar('").append(p[0]).append(':').append(p[1]).append(":").append(d.range().isEmpty()?"["+p[2]+"]":d.range()).append("') { version { prefer '").append(p[2]).append("' } }\n");}}
  s.append("}\n");if(neo&&(c.localLibraries()||c.dependencies().stream().anyMatch(d->d.mode()==Mode.LIBRARY||d.mode()==Mode.EMBED||d.mode()==Mode.MOD&&d.type().equals("required")))){s.append("runs { configureEach { dependencies {\n");if(c.localLibraries())s.append("    runtime project.files(project.fileTree(dir: 'libraries', includes: ['*.jar', '*.JAR']))\n");for(var d:c.dependencies())if(d.mode()==Mode.LIBRARY||d.mode()==Mode.EMBED||d.mode()==Mode.MOD&&d.type().equals("required"))s.append("    runtime '").append(d.coordinate()).append("'\n");s.append("} } }\n");}
  if(c.dependencies().stream().anyMatch(d->d.mode()==Mode.EMBED))s.append("tasks.named('build') { dependsOn tasks.named('jarJar') }\n");if(neo&&c.dependencies().stream().anyMatch(d->d.mode()==Mode.MOD&&d.type().equals("optional"))){s.append("if (providers.gradleProperty('genesis.optionalMods').map { it.toBoolean() }.getOrElse(false)) {\nruns { configureEach { dependencies {\n");for(var d:c.dependencies())if(d.mode()==Mode.MOD&&d.type().equals("optional"))s.append("    runtime '").append(d.coordinate()).append("'\n");s.append("} } }\n}\n");}return s.toString();
 } private static String legacyScript(Config c,boolean neo){
  var s=new StringBuilder("// Generated by Genesis; edit through the dependency manager\nrepositories {\n    mavenCentral()\n");for(String r:c.repositories())s.append("    maven { url = uri('").append(r).append("') }\n");s.append("}\ndependencies {\n");if(c.localLibraries())s.append("    implementation fileTree(dir: 'libraries', includes: ['*.jar', '*.JAR'])\n");
  for(var d:c.dependencies()){String configuration=d.mode()==Mode.COMPILE_ONLY?"compileOnly":d.mode()==Mode.MOD&&d.type().equals("optional")?"compileOnly":"implementation";s.append("    ").append(configuration).append(" '").append(d.coordinate()).append("'\n");if(d.mode()==Mode.EMBED){String[] p=d.coordinate().split(":");s.append("    jarJar('").append(p[0]).append(':').append(p[1]).append(":").append(d.range().isEmpty()?"["+p[2]+"]":d.range()).append("') { version { prefer '").append(p[2]).append("' } }\n");}}
  s.append("}\n");if(neo&&(c.localLibraries()||c.dependencies().stream().anyMatch(d->d.mode()==Mode.LIBRARY||d.mode()==Mode.EMBED))){s.append("runs { configureEach { dependencies {\n");if(c.localLibraries())s.append("    runtime project.files(project.fileTree(dir: 'libraries', includes: ['*.jar', '*.JAR']))\n");for(var d:c.dependencies())if(d.mode()==Mode.LIBRARY||d.mode()==Mode.EMBED)s.append("    runtime '").append(d.coordinate()).append("'\n");s.append("} } }\n");}
  if(c.dependencies().stream().anyMatch(d->d.mode()==Mode.EMBED))s.append("tasks.named('build') { dependsOn tasks.named('jarJar') }\n");return s.toString();
 }
}
